// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PutClinicDocumentProfile Set the legal name, address and tax registration printed on patient documents
	// (PUT /v1/clinics/{clinicId}/document-profile)
	PutClinicDocumentProfile(ctx context.Context, request PutClinicDocumentProfileRequestObject) (PutClinicDocumentProfileResponseObject, error)
	// ListClinicPayments Payments and refunds of my clinic (no patient identity)
	// (GET /v1/clinics/{clinicId}/payments)
	ListClinicPayments(ctx context.Context, request ListClinicPaymentsRequestObject) (ListClinicPaymentsResponseObject, error)
	// GetClinicPaymentsStatus Whether new bookings are paused because refunds could not be paid
	// (GET /v1/clinics/{clinicId}/payments/status)
	GetClinicPaymentsStatus(ctx context.Context, request GetClinicPaymentsStatusRequestObject) (GetClinicPaymentsStatusResponseObject, error)
	// RetryClinicRefund Retry a refund that waited for clinic balance (after topping up)
	// (POST /v1/clinics/{clinicId}/refunds/{refundId}/retry)
	RetryClinicRefund(ctx context.Context, request RetryClinicRefundRequestObject) (RetryClinicRefundResponseObject, error)
	// GetMyAppointmentPayment Status of the payment for my appointment
	// (GET /v1/me/appointments/{appointmentId}/payment)
	GetMyAppointmentPayment(ctx context.Context, request GetMyAppointmentPaymentRequestObject) (GetMyAppointmentPaymentResponseObject, error)
	// GetMyPaymentDocument The receipt or bill of supply for my appointment's payment, issued in the clinic's name
	// (GET /v1/me/appointments/{appointmentId}/payment-document)
	GetMyPaymentDocument(ctx context.Context, request GetMyPaymentDocumentRequestObject) (GetMyPaymentDocumentResponseObject, error)
	// GetMyAppointmentRefund Status of the refund for my appointment, with its reference number
	// (GET /v1/me/appointments/{appointmentId}/refund)
	GetMyAppointmentRefund(ctx context.Context, request GetMyAppointmentRefundRequestObject) (GetMyAppointmentRefundResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

